function deployGum(){if(!gameOn||paused||ended)return;if(gumBarrier&&gumBarrier.userData.life>0){showToast('BOLA DE CHICLETE JÁ ATIVA');return}const dir=new THREE.Vector3(0,0,1).applyQuaternion(playerGroup.quaternion);const pos=player.pos.clone().add(dir.multiplyScalar(3.1));pos.y=.1;
